      if (str1[i - 1] === str2[j - 1]) {
        // Characters match, no edit needed
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        // Take the minimum of insert, delete, or substitute + 1
        dp[i][j] = 1 + Math.min(
          dp[i - 1][j],      // deletion from str1
          dp[i][j - 1],      // insertion into str1
          dp[i - 1][j - 1]   // substitution
        );
      }
    }
  }

  return dp[m][n];
}

/**
