  /**
   * Diagnoses a missing property binding and returns enhanced error info.
   * 
   * @param {string} propertyName - The name of the property that failed to bind
   * @returns {Object} An object with error details, available properties, and suggestions
   */
  function diagnoseMissingProperty(propertyName) {
    const result = {
      error: true,
      missingProperty: propertyName,
      availableProperties: availableProperties,
      suggestion: null
    };

    // Check if the property exists at all (for informational purposes)
    const exists = availableProperties.includes(propertyName);
    result.exists = exists;

    if (exists) {
      result.error = false;
      result.message = `Property '${propertyName}' is defined on the ViewModel.`;
      return result;
    }

    // Find the closest matching property using Levenshtein distance
    let closestMatch = null;
    let minDistance = Infinity;

    for (const prop of availableProperties) {
      const distance = levenshteinDistance(propertyName, prop);

      // Only consider matches within threshold of 3
      if (distance <= 3) {
        if (distance < minDistance || 
            (distance === minDistance && prop < closestMatch)) {
          minDistance = distance;
          closestMatch = prop;
        }
      }
    }

    result.suggestion = closestMatch;

    return result;
  }

  return {
    diagnoseMissingProperty: diagnoseMissingProperty,
    getAvailableProperties: function() {
      return availableProperties.slice();
    }
  };
}

